  "implementation": "import math

def solve(case):
    matrix = case['matrix']
    if not matrix or not matrix[0]:
        raise ValueError('Empty matrix')
    n_rows = len(matrix)
    n_cols = len(matrix[0])
    # Validate rectangular
    for row in matrix:
        if len(row) != n_cols:
            raise ValueError('Non-rectangular matrix')
    # Compute document frequency per column
    df = [0] * n_cols
    for row in matrix:
        for j, val in enumerate(row):
            if val != 0:
                df[j] += 1
    # Compute IDF
    idf = [math.log(1 + n_rows / (1 + d)) for d in df]
    # Build weighted matrix and row degrees
    weighted_matrix = []
    row_degree = []
    for row in matrix:
        weighted_row = [val * idf[j] for j, val in enumerate(row)]
        weighted_matrix.append(weighted_row)
        row_degree.append(sum(weighted_row))
    return {
        'idf': idf,
        'weighted_matrix': weighted_matrix,
        'row_degree': row_degree
    }
